CREATE TABLE recruitment_source (id BIGINT NOT NULL AUTO_INCREMENT,source_code VARCHAR(64) NOT NULL,source_name VARCHAR(255) NOT NULL,source_type VARCHAR(32) NOT NULL,list_url VARCHAR(1000) NOT NULL,enabled TINYINT NOT NULL DEFAULT 1,last_fetch_time DATETIME DEFAULT NULL,last_fetch_status VARCHAR(255) DEFAULT NULL,created_at DATETIME DEFAULT NULL,updated_at DATETIME DEFAULT NULL,PRIMARY KEY(id),UNIQUE KEY uk_recruitment_source_code(source_code));
CREATE TABLE recruitment_notice (id BIGINT NOT NULL AUTO_INCREMENT,source_id BIGINT NOT NULL,title VARCHAR(1000) NOT NULL,notice_url VARCHAR(512) NOT NULL,publish_date DATETIME DEFAULT NULL,notice_type VARCHAR(32) NOT NULL,parent_notice_id BIGINT DEFAULT NULL,user_status VARCHAR(32) NOT NULL,viewed_at DATETIME DEFAULT NULL,discovered_at DATETIME NOT NULL,created_at DATETIME DEFAULT NULL,updated_at DATETIME DEFAULT NULL,PRIMARY KEY(id),UNIQUE KEY uk_recruitment_notice_source_url(source_id,notice_url),KEY idx_recruitment_notice_status(user_status),CONSTRAINT fk_recruitment_notice_source FOREIGN KEY(source_id) REFERENCES recruitment_source(id));
